mapper.select:
SELECT KEY1 label,key1 value,NVL(key4,'N') flag FROM A1_MFG.COMMENT_SUMMARY WHERE FUNCTION_NAME = 'OUTPUT_REVIEW_EQPG_MAINTAIN' AND KEY2 =#{module,jdbcType=VARCHAR}
AND nvl(key4,'N') = 'Y'
ORDER BY DECODE(NVL(key4,'N'),'Y',1,2), UPDATE_TIME

SELECT 1 FROM(
SELECT DISTINCT EQP_G FROM PWEB.EQP_ID_USE_STD@A1PDW  WHERE MODULE = #{MODULE,jdbcType=VARCHAR} AND EQP_G = #{EQP_G,jdbcType=VARCHAR}
UNION
SELECT DISTINCT EQP_G FROM PWEB.EQP_ID_USE_STD@A3PDW  WHERE MODULE = #{MODULE,jdbcType=VARCHAR} AND EQP_G = #{EQP_G,jdbcType=VARCHAR}
)A LEFT JOIN
(
SELECT KEY1 EQP_G,KEY2 MODULE  FROM A1_MFG.COMMENT_SUMMARY WHERE FUNCTION_NAME = 'OUTPUT_REVIEW_EQPG_MAINTAIN'
)B
ON A.EQP_G = B.EQP_G
WHERE A.EQP_G IS NOT NULL AND B.EQP_G IS NULL

mapper.update:
update A1_MFG.COMMENT_SUMMARY set KEY4 = #{FLAG,jdbcType=VARCHAR},UPDATE_TIME = sysdate,UPDATE_USER = #{username,jdbcType=VARCHAR}
where FUNCTION_NAME = 'OUTPUT_REVIEW_EQPG_MAINTAIN'
and KEY1 = #{EQP_G,jdbcType=VARCHAR} and KEY2 = #{MODULE,jdbcType=VARCHAR}

mapper.select:
SELECT EQP_G,F_COMMENT,F_COMMENT2 ,VERSION
FROM A1_MFG.OUTPUT_REVIEW_KEYIN_COMMENT
WHERE EQP_G = #{eqpg,jdbcType=VARCHAR} AND SHIFT_MONTH=#{curMonth,jdbcType=VARCHAR}

merge into A1_MFG.COMMENT_SUMMARY t using (
select 'OUTPUT_MAKEUP_PLAN_PC' FUNCTION_NAME, #{item.FAB,jdbcType=VARCHAR} FAB,#{item.SHIFT_DATE,jdbcType=VARCHAR} SHIFT_DATE,#{item.MAKEUP_PLAN,jdbcType=VARCHAR} MAKEUP_PLAN ,#{username,jdbcType=VARCHAR} UPD_USER from dual
)s on (t.KEY1 = s.FAB AND t.KEY2 = s.SHIFT_DATE AND T.FUNCTION_NAME = S.FUNCTION_NAME) when matched then update set t.KEY3 = s.MAKEUP_PLAN,t.UPDATE_USER = s.UPD_USER,t.UPDATE_TIME = sysdate when not matched then insert (FUNCTION_NAME,KEY1,KEY2,KEY3,UPDATE_USER,UPDATE_TIME) values (s.FUNCTION_NAME,s.FAB,s.SHIFT_DATE,s.MAKEUP_PLAN,s.UPD_USER,sysdate)

mapper.update:
UPDATE A1_MFG.OUTPUT_REVIEW_EQPG_MOVE_TARGET
SET MENU_TARGET = #{MENU_TARGET,jdbcType=INTEGER},UPDATE_TIME = sysdate,UPDATE_USER = #{UPD_USER,jdbcType=VARCHAR}
WHERE SHIFT_MONTH = #{SHIFT_MONTH,jdbcType=VARCHAR} AND EQP_G = #{EQP_G,jdbcType=VARCHAR}
AND FAB = #{FAB,jdbcType=VARCHAR}
